   LinearLayout heading=new LinearLayout(c);heading.setGravity(Gravity.CENTER_VERTICAL);
   FrameLayout mark=new FrameLayout(c);mark.setBackground(Glass.material(c,220,14,Glass.secondary(c)));mark.addView(Icons.view(c,"wallet",Glass.accent(c),23),new FrameLayout.LayoutParams(Glass.dp(c,23),Glass.dp(c,23),Gravity.CENTER));LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(Glass.dp(c,42),Glass.dp(c,42));mp.rightMargin=Glass.dp(c,12);heading.addView(mark,mp);LinearLayout words=new LinearLayout(c);words.setOrientation(LinearLayout.VERTICAL);TextView badge=Glass.text(c,"BOLSILLO",9,true);badge.setLetterSpacing(.18f);badge.setTextColor(Glass.subtle(c));words.addView(badge);TextView headingTitle=Glass.text(c,"Registrar",23,false);headingTitle.setTypeface(Glass.font(c,500));words.addView(headingTitle);heading.addView(words,new LinearLayout.LayoutParams(0,-2,1));
   View close=Modern.iconButton(c,"close","Cerrar registro rápido",dialog::dismiss);heading.addView(close,new LinearLayout.LayoutParams(Glass.dp(c,44),Glass.dp(c,44)));root.addView(heading);root.collapsingHeader=heading;
   ScrollView scroll=new ScrollView(c);scroll.setFillViewport(false);scroll.setClipToPadding(false);scroll.setVerticalScrollBarEnabled(false);body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(0,Glass.dp(c,14),0,Glass.dp(c,10));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
